vec3 rgb_to_hsv(vec3 rgb)
{
    float cmax = max(max(rgb.x, rgb.y), rgb.z);
    float cmin = min(min(rgb.x, rgb.y), rgb.z);
    float delta = cmax - cmin;

    // hue:
    float h = 0.;

    if (delta != 0.)
    {
        if (cmax == rgb.x) h = 60. * mod(((rgb.y-rgb.z)/delta), 6.);
        if (cmax == rgb.y) h = 60. * ((rgb.z - rgb.x) / delta + 2.);
        if (cmax == rgb.z) h = 60. * ((rgb.x - rgb.y) / delta + 4.);
    }

    // saturation:
    float s = 0.;
    if (cmax != 0.) s = delta / cmax;

    // value:
    float v = cmax;


    return vec3(h, s, v); 
}

vec3 hsv_to_rgb(vec3 hsv)
{
    float c = hsv.z * hsv.y;
    float x = c * (1. - abs(mod(hsv.x / 60., 2.) - 1.));
    float m = hsv.z - c;

    vec3 rgb;

    if (hsv.x < 60.)       rgb = vec3(c, x, 0);
    else if (hsv.x < 120.) rgb = vec3(x, c, 0);
    else if (hsv.x < 180.) rgb = vec3(0, c, x);
    else if (hsv.x < 240.) rgb = vec3(0, x, c);
    else if (hsv.x < 300.) rgb = vec3(x, 0, c);
    else                   rgb = vec3(c, 0, x);

    rgb += vec3(m);

    return rgb;
}

vec3 rainbow(vec2 uv)
{
    float g = 1.5 *(sin(iTime) + 1.) + 1.01;

    vec3 top_left_color = vec3(1, 1, 1.-g);
    vec3 top_right_color = vec3(1, 0, 1.-g);
    vec3 btm_left_color = vec3(1, 0, g);
    vec3 btm_right_color = vec3(1, 1, g);

    top_left_color = rgb_to_hsv(top_left_color);
    top_right_color = rgb_to_hsv(top_right_color);
    btm_left_color = rgb_to_hsv(btm_left_color);
    btm_right_color = rgb_to_hsv(btm_right_color);

    vec3 c0 = uv.x * (top_right_color - top_left_color) + top_left_color;
    vec3 c1 = uv.x * (btm_right_color - btm_left_color) + btm_left_color;

    vec3 c = uv.y * (c0 - c1) + c1;

    return hsv_to_rgb(c);
}

vec3 rainbow1(vec2 uv)
{
    float g = sin(iTime * 1.5) / 2. + 0.5;
    if (g < 0.01) g = 0.01;
    if (g > 0.99) g = 0.99;

    vec3 top_left_color = vec3(g, 1, 1.-g);
    vec3 top_right_color = vec3(1, 0, 1.-g);
    vec3 btm_left_color = vec3(g, 0, 1);
    vec3 btm_right_color = vec3(1, 1, g);

    top_left_color = rgb_to_hsv(top_left_color);
    top_right_color = rgb_to_hsv(top_right_color);
    btm_left_color = rgb_to_hsv(btm_left_color);
    btm_right_color = rgb_to_hsv(btm_right_color);

    vec3 c0 = uv.x * (top_right_color - top_left_color) + top_left_color;
    vec3 c1 = uv.x * (btm_right_color - btm_left_color) + btm_left_color;

    vec3 c = uv.y * (c0 - c1) + c1;

    return hsv_to_rgb(c);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    vec3 c = rainbow(fragCoord/iResolution.xy);
    vec3 c1 = rainbow1(fragCoord/iResolution.xy);

    fragColor = vec4((c+c1)/2.,1.0);
}
